import {analyzeDNA,teachingDNA} from './studio-science.js';
export function pondModel(nutrients,plants){const n=Math.max(0,Math.min(100,Number(nutrients))),p=Math.max(0,Math.min(100,Number(plants)));return {nutrients:n,plants:p,oxygen:Math.round(Math.max(0,Math.min(100,82+.15*p-.65*n))),algae:Math.round(n*.8)}}
export const foodEdges=['plant>rabbit','rabbit>snake','snake>hawk','plant>decomposer','rabbit>decomposer','snake>decomposer','hawk>decomposer'];
export function foodWebValid(edges){return foodEdges.every(edge=>edges.includes(edge))&&edges.every(edge=>foodEdges.includes(edge))}
export function questExperimentValid(id,values){
 if(id==='pond'){const m=pondModel(values.nutrients,values.plants);return m.nutrients<=30&&m.oxygen>=60}
 if(id==='corridor')return Number(values.connectivity)>=65;
 if(id==='code'){const r=analyzeDNA(values.dna||'');return r.valid&&r.dna!==teachingDNA&&r.dna.length===teachingDNA.length&&r.dna.slice(0,3)===teachingDNA.slice(0,3)&&r.dna.slice(6)===teachingDNA.slice(6)&&r.dna.slice(3,6)==='GAG'}
 if(id==='web')return foodWebValid(values.edges||[]);
 return id==='outbreak'&&values.factor==='water'&&values.control==='same-other';
}
